import { Gesture, GestureDetector } from 'react-native-gesture-handler'
import Animated, {
	runOnJS,
	useAnimatedStyle,
	useSharedValue,
	withSpring
} from 'react-native-reanimated'
import { LayoutChangeEvent, Text, View } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useState } from 'react'
import * as Haptics from 'expo-haptics'

interface SnapSliderProps {
	snapPoints: number[]
	value: number
	onChange: (value: number) => void
}

export function SnapSlider({ snapPoints, value, onChange }: SnapSliderProps) {
	const { theme } = useTheme()
	const [sliderWidth, setSliderWidth] = useState(0)
	const translateX = useSharedValue(0)
	const width = useSharedValue(0)
	const currentSnapIndex = useSharedValue(-1)

	const triggerHaptic = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
	}

	const handleLayout = (event: LayoutChangeEvent) => {
		const layoutWidth = event.nativeEvent.layout.width
		setSliderWidth(layoutWidth)
		width.set(layoutWidth)
		const valueIndex = snapPoints.indexOf(value)
		if (valueIndex !== -1) {
			const segmentWidth = layoutWidth / (snapPoints.length - 1)
			translateX.set(valueIndex * segmentWidth)
			currentSnapIndex.set(valueIndex)
		}
	}

	const findNearestSnapAndUpdate = (position: number) => {
		'worklet'
		if (width.get() === 0) return
		const segmentWidth = width.get() / (snapPoints.length - 1)
		const segmentIndex = Math.round(position / segmentWidth)
		const clampedIndex = Math.max(
			0,
			Math.min(snapPoints.length - 1, segmentIndex)
		)
		const nearestSnap = snapPoints[clampedIndex]
		translateX.set(withSpring(clampedIndex * segmentWidth))
		runOnJS(triggerHaptic)()
		runOnJS(onChange)(nearestSnap)
	}

	const panGesture = Gesture.Pan()
		.onChange((event) => {
			'worklet'
			if (width.get() === 0) return
			const previousX = translateX.get()
			const newX = Math.max(
				0,
				Math.min(width.get(), translateX.get() + event.changeX)
			)
			translateX.set(newX)

			const segmentWidth = width.get() / (snapPoints.length - 1)
			const threshold = segmentWidth * 0.1

			for (let i = 0; i < snapPoints.length; i++) {
				const snapPosition = i * segmentWidth
				const crossedSnap =
					(previousX < snapPosition && newX >= snapPosition) ||
					(previousX > snapPosition && newX <= snapPosition)

				if (crossedSnap && Math.abs(newX - snapPosition) < threshold) {
					if (currentSnapIndex.get() !== i) {
						currentSnapIndex.set(i)
						runOnJS(onChange)(snapPoints[i])
					}
					break
				}
			}
		})
		.onEnd(() => {
			findNearestSnapAndUpdate(translateX.get())
		})

	const tapGesture = Gesture.Tap().onEnd((event) => {
		'worklet'
		if (width.get() === 0) return
		findNearestSnapAndUpdate(event.x)
	})

	const gesture = Gesture.Race(panGesture, tapGesture)

	const filledStyle = useAnimatedStyle(() => ({
		width: Math.max(0, translateX.get())
	}))

	const indicatorStyle = useAnimatedStyle(() => ({
		transform: [
			{
				translateX: Math.min(
					sliderWidth - 14,
					Math.max(-2, translateX.get() - 8)
				)
			}
		]
	}))

	const thumbStyle = useAnimatedStyle(() => ({
		transform: [{ translateX: translateX.get() }]
	}))

	if (sliderWidth === 0) {
		return <View style={styles.wrapper} onLayout={handleLayout} />
	}

	return (
		<View style={styles.wrapper}>
			<GestureDetector gesture={gesture}>
				<View style={styles.container}>
					<View style={[styles.track(theme)]}>
						<Animated.View style={[styles.filled(theme), filledStyle]} />
					</View>
					<Animated.View style={[styles.indicator(theme), indicatorStyle]} />
					<Animated.View style={[styles.thumb, thumbStyle]} />
				</View>
			</GestureDetector>
			<View style={styles.dotsAndLabelsContainer}>
				{snapPoints.map((point, index) => {
					const isActive = point === value
					const segmentWidth = sliderWidth / (snapPoints.length - 1)
					const position = index * segmentWidth
					const centerIndex = Math.floor(snapPoints.length / 2)
					const isFirst = index === 0
					const isLast = index === snapPoints.length - 1
					const showLabel = isFirst || index === centerIndex || isLast

					return (
						<View
							key={index}
							style={[
								styles.label,
								{
									left: position
								}
							]}
						>
							<View
								style={styles.snapPoint(theme, isActive, isFirst, isLast)}
							/>
							{showLabel && (
								<Text
									style={styles.labelText(theme, isActive, isFirst, isLast)}
								>
									{point}k
								</Text>
							)}
						</View>
					)
				})}
			</View>
		</View>
	)
}

const styles = defineStyles({
	wrapper: {
		gap: 10
	},
	container: {
		justifyContent: 'center'
	},
	track: (theme: Theme) => ({
		height: 8,
		borderRadius: 99,
		overflow: 'hidden',
		backgroundColor: colors[theme].gray[400]
	}),
	filled: (theme: Theme) => ({
		height: 8,
		borderRadius: 99,
		position: 'absolute',
		backgroundColor: colors[theme].background,
		minWidth: '3%'
	}),
	indicator: (theme: Theme) => ({
		width: 16,
		height: 16,
		position: 'absolute',
		top: -4,
		borderRadius: 99,
		backgroundColor: colors[theme].background
	}),
	dotsAndLabelsContainer: {
		position: 'relative',
		height: 28
	},
	label: {
		position: 'absolute',
		alignItems: 'center',
		gap: 6,
		transform: [{ translateX: '-50%' }]
	},
	snapPoint: (
		theme: Theme,
		isActive?: boolean,
		isFirst?: boolean,
		isLast?: boolean
	) => ({
		width: 4,
		height: 4,
		borderRadius: 4,
		backgroundColor: isActive
			? colors[theme].background
			: colors[theme].gray[400],
		marginLeft: isFirst ? '10%' : 0,
		marginRight: isLast ? '10%' : 0
	}),
	thumb: {
		width: 44,
		height: 44,
		position: 'absolute',
		marginLeft: -22
	},
	labelText: (
		theme: Theme,
		isActive?: boolean,
		isFirst?: boolean,
		isLast?: boolean
	) => ({
		fontSize: 14,
		fontWeight: '500',
		color: isActive ? colors[theme].gray[25] : colors[theme].gray[400],
		marginLeft: isFirst ? '30%' : 0,
		marginRight: isLast ? '30%' : 0
	})
})
